window.LD=window.LD||{};window.LD["party/p4"]={"id":"p4","name":"The Tidal Almanac","poss":"The Tidal Almanac's","members":["h10","h14","h16","h17"],"leader":"h10","morale":97,"disposition":"wary","motto":"We'll find out.","banner":{"c1":"#2f9e9e","c2":"#e8c83a","emblem":"star"},"loc":"sunken_vault","loc_name":"The Sunken Vault","goal":{"text":"to earn 500 silver between them before the season ends","kind":"purse","done":75,"progress":"1,202 silver, past the 500 aimed for","missed":false,"crew":"The Tidal Almanac","party":"p4"},"vows":[{"text":"never to retreat","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Tidal Almanac","party":"p4"},{"text":"to die rich","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Tidal Almanac","party":"p4"}],"doing":"last seen delving into The Sunken Vault","progress":null,"today":["Fought 1 fight: won 1; 1 foe down.","XP: Juniper +252, Ottoline +252, Tamsin +261, Fenwick +252.","Coin between them: +157 silver.","Came away with 18 fangs & claws, a gem, a healing potion, a trinket.","Ate 8 rations.","Used up 3 torches.","Tamsin: new gear, Salt-Hardened Pathfinder's Boots."],"fights_today":["f217"],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":204,"season":{"wins":10,"bosses":0,"floors":6,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":3},"career":{"wins":25,"bosses":0,"floors":12,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":10},"former":["h17"],"fallen":[],"travel":null,"wagon":{"kind":"donkey_cart","name":"The Barrel","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":53,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"pony","name":"Muffin","label":"pony","colour":"buckskin","owner":"Juniper"},"paid":[["Ottoline",4],["Tamsin",4],["Juniper",1]]},"pace_gap":14,"rels":[{"party":"p3","score":100},{"party":"p6","score":63},{"party":"p2","score":2}],"events":[{"id":"e31","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Juniper and Ottoline shake on it at The Drowned Gull: they are now The Tidal Almanac. (Honorable, by the look of them.)","heroes":["h10","h14"],"parties":["p4"],"loc":"saltmarrow"},{"id":"e670","day":20,"season":1,"sday":20,"kind":"fight","imp":2,"text":"Back in the Salt Cliffs, the Tidal Almanac handles 3 Cliff Crabs and a Siren. Four of them felt Ottoline's Steam Burst in the same breath. Loot: 7 chitin, 3 cliff crab claws, 1 gem.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"saltcliffs","fight":"f51","foes":["crab","crab","siren"],"where":"in The Salt Cliffs","won":true,"close":false,"shape":"again","reworded":-6},{"id":"e671","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"Ottoline lights the campfire by breathing on it. Juniper has seen this forty times and still claps.","heroes":["h14","h10"],"parties":["p4"],"loc":"saltcliffs","skill":"fire_eater"},{"id":"e719","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"The Tidal Almanac dispatches 4 Cliff Crabs in the Salt Cliffs, in thick fog. Tamsin's Aimed Shot found the cliff crab from the back row. Ottoline took the knocks meant for the others and kept quiet about the bruises. Loot: 6 chitin, 5 cliff crab claws, 5 fish.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"saltcliffs","fight":"f53","foes":["crab","crab","crab"],"where":"in The Salt Cliffs","won":true,"close":false,"shape":"weather","reworded":-14,"wx":"fog"},{"id":"e734","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Tamsin sharpens the crew's knives by firelight, one long stroke at a time. The sound is oddly calming.","heroes":["h16"],"parties":["p4"],"loc":"saltcliffs","skill":"whetstone","wx":"fog"},{"id":"e769","day":22,"season":1,"sday":22,"kind":"ambush","imp":3,"text":"The Tidal Almanac runs for it on the road to Saltmarrow, routed by 4 Drakes. Ottoline was first out the door and would like that kept quiet. Juniper has to be dragged out. Injured: Juniper (sprained ankle).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"saltcliffs","fight":"f55","foes":["drake","drake","drake"],"where":"on the road to Saltmarrow","won":false,"close":true,"shape":"plain","reworded":6,"wx":"fog"},{"id":"e779","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Juniper spends the evening at the Saltmarrow tavern doing sums on a napkin. The sums come out well.","heroes":["h10"],"parties":["p4"],"loc":"saltmarrow","skill":"bulk_trader","wx":"fog"},{"id":"e792","day":22,"season":1,"sday":22,"kind":"argument","imp":2,"text":"Ottoline and Tamsin spend supper disagreeing about Ottoline's snoring, politely at first.","heroes":["h14","h16"],"parties":["p4"]},{"id":"e793","day":22,"season":1,"sday":22,"kind":"campfire","imp":2,"text":"Ottoline notices Juniper has the same boots, a size bigger. Neither knows what to do with this.","heroes":["h10","h14"],"parties":["p4"],"loc":"saltmarrow","wx":"fog"},{"id":"e823","day":23,"season":1,"sday":23,"kind":"campfire","imp":1,"text":"Juniper offers Tamsin a sip of ale. Tamsin declines, then accepts.","heroes":["h10","h16"],"parties":["p4"],"loc":"saltmarrow","wx":"fog"},{"id":"e828","day":24,"season":1,"sday":24,"kind":"road","imp":3,"text":"Captain Mabb challenges Tamsin to a race to the next town for bragging rights. Tamsin wins by a mile. The mule wins the sulk.","heroes":["h16","h10","h14"],"parties":["p4"],"road":"carrbridge~saltmarrow","traveller":"fourth_best","road_rec":"r179"},{"id":"e870","day":25,"season":1,"sday":25,"kind":"road","imp":3,"text":"Juniper kicks a stone on the road to Carrbridge and a clay jar rolls out of the verge, full of old coins stamped with a king nobody remembers. Juniper keeps what the law allows, which is most of it.","heroes":["h10","h14","h16"],"parties":["p4"],"road":"carrbridge~saltmarrow","road_rec":"r185"},{"id":"e907","day":26,"season":1,"sday":26,"kind":"sniped","imp":3,"text":"News for The Tidal Almanac and Tobias: Old Grizzlemaw is dead, killed by Fenwick today. Some sharpened swords for nothing, and all of them pick new roads.","heroes":["h10","h14","h16","h17","h6"],"parties":["p4"],"loc":"wolf_den","snipers":["h17"],"where":"many","boss":"Old Grizzlemaw","in_fight":"f63","wx":"fog"},{"id":"e927","day":26,"season":1,"sday":26,"kind":"goal_conceded","imp":3,"text":"Fenwick got to Old Grizzlemaw first. The Tidal Almanac concedes the season goal, mutters something about next time, and settles on a new one: to earn 300 silver between them before the season ends.","heroes":["h10","h14","h16"],"parties":["p4"]},{"id":"e947","day":27,"season":1,"sday":27,"kind":"journey","imp":2,"text":"On the way to Ashfen, Azure Edge catches up with The Tidal Almanac. The conversation turns to Morwen's terrible singing and never recovers.","heroes":["h3","h9","h1","h5","h10","h14","h16"],"parties":["p3","p4"]},{"id":"e960","day":28,"season":1,"sday":28,"kind":"road","imp":3,"text":"Ottoline meets Captain Dorrit Salt for the first time, striding with a spyglass and a sailor's roll, shouting at the road to hold a steady course.","heroes":["h14","h10","h16"],"parties":["p4"],"road":"ashfen~carrbridge","traveller":"salt","road_rec":"r201"},{"id":"e970","day":28,"season":1,"sday":28,"kind":"boss_race","imp":3,"text":"Vessimir the Unburied has visitors coming. Azure Edge and The Tidal Almanac are both on the way to the Ashveil Crypts, and nobody is waiting for the others.","heroes":["h3","h9","h1","h5","h10","h14","h16"],"parties":["p3","p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1005","day":29,"season":1,"sday":29,"kind":"meet","imp":1,"text":"Azure Edge runs into The Tidal Almanac in the Ashveil Crypts. Stories are exchanged, most of them exaggerated.","heroes":["h3","h9","h1","h5","h10","h14","h16"],"parties":["p3","p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1011","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Ottoline makes a tiny storm over Juniper's tea: lightning, hail, a small rainbow. Juniper drinks it anyway.","heroes":["h14","h10"],"parties":["p4"],"loc":"ashveil_crypts","skill":"elemental_tricks","wx":"fog"},{"id":"e1012","day":29,"season":1,"sday":29,"kind":"campfire","imp":1,"text":"Tamsin and Ottoline walk point together all afternoon and say about nine words. Good words.","heroes":["h16","h14"],"parties":["p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1026","day":30,"season":1,"sday":30,"kind":"delve","imp":1,"text":"The Tidal Almanac descends into the Ashveil Crypts, mostly explored (75%).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1036","day":30,"season":1,"sday":30,"kind":"campfire","imp":3,"text":"Tamsin and Ottoline end up on the same rope across a stream and have to trust each other for a minute.","heroes":["h16","h14"],"parties":["p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1039","day":30,"season":1,"sday":30,"kind":"delve_done","imp":1,"text":"The Ashveil Crypts is behind The Tidal Almanac now: a day down there, and the sky looks enormous. They made it to floor 2.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"ashveil_crypts","days":1,"bottom":false,"rooms":[],"gold":0,"wx":"fog"},{"id":"e1040","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Ottoline smooths out the third-place ribbon and pins it inside their coat. Third is a place.","heroes":["h14"],"parties":["p4"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1046","day":30,"season":1,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Tidal Almanac came up short: earn 300 silver between them before the season ends (13 of 300 silver).","heroes":["h10","h14","h16"],"parties":["p4"]},{"id":"e1064","day":31,"season":2,"sday":1,"kind":"road","imp":3,"text":"A lamp goes out in a storm. Juniper climbs the post in the wind and relights it, to a small cheer from the lamplighter below.","heroes":["h10","h14","h16"],"parties":["p4"],"road":"carrbridge~saltmarrow","traveller":"hetty","road_rec":"r221"},{"id":"e1082","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"The Mimic King's Ghost has visitors coming. The Gravediggers of Ironhaven, Azure Edge and The Tidal Almanac are all on the way to Cragtooth Warren, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h3","h9","h1","h5","h10","h14","h16"],"parties":["p2","p3","p4"],"loc":"cragtooth_warren"},{"id":"e1091","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Tamsin hitches a ride on a hay cart they knew would be passing at noon, naps all the way, and steps off healed and smiling.","heroes":["h16"],"parties":["p4"],"loc":"saltmarrow","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true},{"id":"e1105","day":31,"season":2,"sday":1,"kind":"argument","imp":1,"text":"Tamsin and Ottoline spend supper disagreeing about which way the road went, politely at first.","heroes":["h16","h14"],"parties":["p4"]},{"id":"e1106","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Juniper and Ottoline, a month into The Tidal Almanac: they walk in step now without trying.","heroes":["h10","h14"],"parties":["p4"],"loc":"saltmarrow"},{"id":"e1110","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Tidal Almanac: never to retreat. Easy to say on day one.","heroes":["h10","h14","h16"],"parties":["p4"]},{"id":"e1168","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"A month in The Tidal Almanac together. Juniper and Tamsin know each other's snores, sorrows and orders by heart.","heroes":["h10","h16"],"parties":["p4"],"loc":"carrbridge","wx":"rain"},{"id":"e1187","day":34,"season":2,"sday":4,"kind":"talent","imp":1,"text":"Travellers in the Ironhaven inn queue up to ask Tamsin the best way home. That's Walker of All Roads for you.","heroes":["h16"],"parties":["p4"],"loc":"ironhaven","skill":"walker_of_all_roads"},{"id":"e1209","day":35,"season":2,"sday":5,"kind":"ambush","imp":2,"text":"On the road to Cragtooth Warren, the Tidal Almanac squares up to 2 Bandit Captains, a Bandit Archer and a Bandit and carries the day. Juniper talks one bandit captain into walking away before it's over. Somewhere around Ottoline's Firebolt, the other side stopped believing. Tamsin never once gave ground. Loot: 22 silver each, a string of bandit sausages, 5 stolen goods.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"kingsroad","fight":"f77","foes":["bandit_archer","bandit","bandit_captain"],"where":"on the road to Cragtooth Warren","won":true,"close":false,"shape":"place","reworded":-28},{"id":"e1210","day":35,"season":2,"sday":5,"kind":"talent","imp":1,"text":"Ottoline lights the campfire by glaring at it.","heroes":["h14"],"parties":["p4"],"loc":"cragtooth_warren","skill":"kindled_soul"},{"id":"e1250","day":36,"season":2,"sday":6,"kind":"delve","imp":1,"text":"The Tidal Almanac descends into Cragtooth Warren, partly explored (48%).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren"},{"id":"e1251","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 1 of Cragtooth Warren at a steady pace: 1 room (the story wall).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":1,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1279","day":37,"season":2,"sday":7,"kind":"gear","imp":4,"text":"Juniper comes out of Cragtooth Warren with an iron hinge worn on a chain, still warm from Gnasher. There is only one of those, and nobody yet knows what it does.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","wx":"storm"},{"id":"e1280","day":37,"season":2,"sday":7,"kind":"famous_trap","imp":4,"text":"Gnasher, the trap everyone in Cragtooth Warren talks about, is disarmed at last. Tamsin did it, and kept a piece as proof.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","wx":"storm"},{"id":"e1281","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Cragtooth Warren at a steady pace: 3 rooms (the cook cave, the gem vein, Gnasher).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["unique"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1282","day":37,"season":2,"sday":7,"kind":"ambush","imp":3,"text":"Two Goblin Archers and a Kobold Slinger pick the wrong crew at their camp on floor 2 of Cragtooth Warren, in the middle of the night, and the Tidal Almanac beats them. Tamsin loosed Aimed Shot, and the goblin archer dropped. Ottoline finished it, quietly, while the others were still catching their breath. Juniper picked the biggest one and did not regret it. \"Everyone all right? Everyone?\" says Juniper. Loot: 5 silver each, 3 goblin ears, 2 kobold firepeppers.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f88","foes":["goblin_archer","kobold_slinger","goblin_archer"],"where":"at their camp on floor 2 of Cragtooth Warren, in the middle of the night","won":true,"close":false,"shape":"foe","reworded":-32,"wx":"storm"},{"id":"e1296","day":37,"season":2,"sday":7,"kind":"sniped","imp":3,"text":"Word reaches The Tidal Almanac on floor 2 of Cragtooth Warren: Azure Edge killed The Mimic King's Ghost today. Nobody says much. The side passages still need mapping.","heroes":["h10","h14","h16","h3","h9","h1","h5"],"parties":["p4","p3"],"loc":"cragtooth_warren","snipers":["h3","h9","h1","h5"],"where":"inside","boss":"The Mimic King's Ghost","in_fight":"f89","wx":"storm"},{"id":"e1302","day":37,"season":2,"sday":7,"kind":"meet","imp":1,"text":"The Tidal Almanac and Azure Edge share a fire in Cragtooth Warren and trade news.","heroes":["h10","h14","h16","h3","h9","h1","h5"],"parties":["p4","p3"],"loc":"cragtooth_warren","wx":"storm"},{"id":"e1307","day":37,"season":2,"sday":7,"kind":"talent","imp":2,"text":"Tamsin names every star over the camp by which road it hangs above.","heroes":["h16"],"parties":["p4"],"loc":"cragtooth_warren","skill":"walker_of_all_roads","wx":"storm"},{"id":"e1308","day":37,"season":2,"sday":7,"kind":"campfire","imp":2,"text":"Juniper patches Ottoline's cloak without being asked. Ottoline pretends not to notice, then says thanks.","heroes":["h14","h10"],"parties":["p4"],"loc":"cragtooth_warren","wx":"storm"},{"id":"e1318","day":38,"season":2,"sday":8,"kind":"fight","imp":3,"text":"With Tamsin hitting hardest, the Tidal Almanac makes short work of a Drake in the drake's warm cave on floor 2 of Cragtooth Warren. Tamsin put Aimed Shot into the drake to end it, and lowered the bow. Loot: 1 drake scale, 2 fangs & claws.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f90","foes":["drake"],"where":"in the drake's warm cave on floor 2 of Cragtooth Warren","won":true,"close":false,"shape":"hero","reworded":-29,"wx":"storm"},{"id":"e1319","day":38,"season":2,"sday":8,"kind":"fight","imp":1,"text":"The Tidal Almanac makes it four wins running, seeing off a Cave Troll in the troll's hollow on floor 2 of Cragtooth Warren. The cave troll spent the rest of the fight on fire, courtesy of Ottoline's Firebolt. Loot: 6 silver each, 1 troll hide, 5 ore.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f91","foes":["cave_troll"],"where":"in the troll's hollow on floor 2 of Cragtooth Warren","won":true,"close":false,"shape":"streak","reworded":-30,"wx":"storm"},{"id":"e1320","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Cragtooth Warren at a steady pace: 3 rooms (the drake's warm cave, the troll's hollow, the kobold larder).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"storm"},{"id":"e1382","day":39,"season":2,"sday":9,"kind":"fight","imp":1,"text":"The Tidal Almanac gets the better of a Cave Slime in the slime sump on floor 2 of Cragtooth Warren. Tamsin waited for the gap and put Aimed Shot through it. Juniper pulled a friend out of trouble and went back in for more. Loot: 2 trinkets.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f96","foes":["slime"],"where":"in the slime sump on floor 2 of Cragtooth Warren","won":true,"close":false,"shape":"plain","reworded":-8},{"id":"e1383","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Cragtooth Warren at a steady pace: 3 rooms (the echo hall, the coin-floored room, the slime sump).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e1384","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Tamsin lists the next three places they want to see. One of them may not exist. Wanderlust, the guild calls it.","heroes":["h16"],"parties":["p4"],"loc":"cragtooth_warren","skill":"wanderlust"},{"id":"e1403","day":39,"season":2,"sday":9,"kind":"argument","imp":3,"text":"Tamsin and Juniper are not speaking. It's about the correct way to sharpen a sword. It's never really about the correct way to sharpen a sword.","heroes":["h16","h10"],"parties":["p4"]},{"id":"e1420","day":40,"season":2,"sday":10,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Cragtooth Warren at a steady pace: 3 rooms (a hidden room behind the slime sump, the chest graveyard, the black cistern).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common","common"],"fears":1,"wild":[]},"wx":"heat"},{"id":"e1450","day":41,"season":2,"sday":11,"kind":"fight","imp":3,"text":"In the new dig on floor 2 of Cragtooth Warren, the Tidal Almanac squares up to 2 Goblin Archers, a Kobold and a Giant Bat and carries the day. Before it's over, Juniper talks one kobold into putting the weapon down. The giant bat went down to Ottoline's Firebolt. Loot: 2 silver each, a pair of bat wings, 3 goblin ears.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","fight":"f98","foes":["kobold","giant_bat","goblin_archer"],"where":"in the new dig on floor 2 of Cragtooth Warren","won":true,"close":false,"shape":"place","reworded":-37,"wx":"heat"},{"id":"e1451","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Cragtooth Warren at a steady pace: 3 rooms (the delvers' last stand, the new dig, the golden gate).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":3,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"heat"},{"id":"e1452","day":41,"season":2,"sday":11,"kind":"delve_done","imp":3,"text":"Up the last steps after 6 days: The Tidal Almanac climbs into the sun and nobody says anything for a while. They went as deep as the place goes, mapped 59% of it, came across Gnasher, the echo hall, a hidden room behind the slime sump and 1 more good room, took 16 rooms off the map's blank side, took the teeth out of 2 traps and came away with 123 silver between them. No boss, but the place paid. Counting every crew that has been down, Cragtooth Warren is picked clean (97%).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"cragtooth_warren","days":6,"bottom":true,"rooms":["Gnasher","the echo hall"],"gold":123,"turn":"floor","wx":"heat"},{"id":"e1453","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"Tamsin briefs the crew on which other parties are feuding, and why. Ottoline takes notes. Tamsin puts it down to Rumourmonger.","heroes":["h16","h14"],"parties":["p4"],"loc":"cragtooth_warren","skill":"rumourmonger","wx":"heat"},{"id":"e1454","day":41,"season":2,"sday":11,"kind":"ability","imp":2,"text":"Everyone thought the food was gone. Juniper rearranges the packs at camp and finds a whole spare ration. Supper is saved, and so is the mood.","heroes":["h10"],"parties":["p4"],"loc":"cragtooth_warren","skill":"stretch_the_rations","sk":"Stretch the Rations","rule":true,"wx":"heat"},{"id":"e1462","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"Ottoline lights a whole dark corridor with a snap and singes only one cobweb too many. (Kindled Soul, if anyone's asking.)","heroes":["h14"],"parties":["p4"],"loc":"cragtooth_warren","skill":"kindled_soul","wx":"heat"},{"id":"e1468","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"Juniper labels every sack in the packs. Tamsin finds the labels oddly comforting.","heroes":["h10","h16"],"parties":["p4"],"loc":"cragtooth_warren","skill":"stretch_the_rations","wx":"heat"},{"id":"e1473","day":41,"season":2,"sday":11,"kind":"goal","imp":1,"text":"The Tidal Almanac sets their sights for the season: to sit beneath the Mother Oak in Hollowood.","heroes":["h10","h14","h16"],"parties":["p4"]},{"id":"e1537","day":43,"season":2,"sday":13,"kind":"road","imp":4,"text":"Captain Mabb asks, very formally, whether the Fourth-Best Company might join Tamsin as hirelings. Tamsin says no, kindly. They take it well and buy the mule a hat.","heroes":["h16","h10","h14"],"parties":["p4"],"road":"ironhaven~thornwall","traveller":"fourth_best","road_rec":"r300"},{"id":"e1541","day":43,"season":2,"sday":13,"kind":"ability","imp":2,"text":"Tamsin turns off the road down a path nobody else can see. Two hours later the party is past the hills, rested and with dry feet.","heroes":["h16"],"parties":["p4"],"loc":"ironhaven","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"storm"},{"id":"e1580","day":44,"season":2,"sday":14,"kind":"vow","imp":2,"text":"Fenwick brings an unfinished vow into The Tidal Almanac: to die rich. They take it on.","heroes":["h17"],"parties":["p4"]},{"id":"e1581","day":44,"season":2,"sday":14,"kind":"party_join","imp":3,"text":"Fenwick joins The Tidal Almanac over drinks in Thornwall. That makes 4.","heroes":["h17","h10","h14","h16"],"parties":["p4"],"loc":"thornwall"},{"id":"e1583","day":44,"season":2,"sday":14,"kind":"talent","imp":2,"text":"A Thornwall chandler closing up shop gives Juniper a cartload of rope. Juniper will find a use. Juniper always does.","heroes":["h10"],"parties":["p4"],"loc":"thornwall","skill":"bulk_trader"},{"id":"e1591","day":44,"season":2,"sday":14,"kind":"argument","imp":1,"text":"Juniper and Fenwick of The Tidal Almanac have a shouting match about the correct way to sharpen a sword.","heroes":["h10","h17"],"parties":["p4"]},{"id":"e1607","day":45,"season":2,"sday":15,"kind":"party_life","imp":1,"text":"Fenwick rides ahead, rides back, rides ahead again. Juniper, Ottoline and Tamsin are not amused.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornwall"},{"id":"e1609","day":45,"season":2,"sday":15,"kind":"night","imp":2,"text":"A carter with a broken wheel on the road to Hollowood pays for The Tidal Almanac's help in gossip: the deep rooms of Frostspire are open again.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornwall"},{"id":"e1615","day":45,"season":2,"sday":15,"kind":"talent","imp":1,"text":"A lost royal courier asks Tamsin for directions and gets them, plus a shortcut. Walker of All Roads all the way, Tamsin insists.","heroes":["h16"],"parties":["p4"],"loc":"thornwall","skill":"walker_of_all_roads"},{"id":"e1619","day":45,"season":2,"sday":15,"kind":"campfire","imp":2,"text":"Ottoline and Tamsin sit out a long silence at The Sagging Beam and find it was not as awkward as feared.","heroes":["h14","h16"],"parties":["p4"],"loc":"thornwall"},{"id":"e1643","day":46,"season":2,"sday":16,"kind":"ambush","imp":2,"text":"Two Bandit Captains and 2 Bandits learn the hard way not to bother the Tidal Almanac on the road to Hollowood. Before it's over, Juniper talks one bandit captain into putting the weapon down. The last bandit breaks and runs. It was even until Ottoline's Force Bolt. Then it wasn't. Tamsin saw every rush coming and shouted it in time. Fenwick toasted the win before the last one had finished falling. \"I'll keep this one's ear,\" says Fenwick. Loot: 20 silver each, 8 stolen goods, 2 gems.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"kingsroad","fight":"f107","foes":["bandit_captain","bandit","bandit_captain"],"where":"on the road to Hollowood","won":true,"close":false,"shape":"foe","reworded":-50},{"id":"e1654","day":46,"season":2,"sday":16,"kind":"campfire","imp":1,"text":"Juniper and Tamsin spend the end of the fight arguing over who dented whose helmet.","heroes":["h10","h16"],"parties":["p4"],"loc":"hollowood"},{"id":"e1658","day":46,"season":2,"sday":16,"kind":"goal_done","imp":4,"text":"PILGRIMAGE: The Tidal Almanac reaches Hollowood at last, and gets to sit beneath the Mother Oak. Nobody says much. Everybody walks back lighter. It was Tamsin's idea in the first place. XP: Juniper +960 (level 12!), Ottoline +927 (level 13!), Tamsin +960 (level 13!), Fenwick +800 (level 13!).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"hollowood","xp":{"h10":960,"h14":927,"h16":960,"h17":800}},{"id":"e1661","day":46,"season":2,"sday":16,"kind":"big_move","imp":3,"text":"Tamsin has now set foot in seven of the realm's towns. On the table: Tamsin +51 renown (16th to 14th). The Tidal Almanac +51 party renown (holds 4th among the crews).","heroes":["h16"],"parties":["p4"],"cause":"e1656","moves":[{"hero":"h16","gain":51,"from":16,"to":14}],"party_moves":[{"party":"p4","gain":51,"from":4,"to":4}]},{"id":"e1685","day":47,"season":2,"sday":17,"kind":"party_life","imp":1,"text":"Juniper, Ottoline and Tamsin ask Fenwick if the view is nice up there. It is.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"hollowood"},{"id":"e1718","day":48,"season":2,"sday":18,"kind":"talent","imp":2,"text":"A Thornwall child asks Fenwick for the biggest thing they ever beat. It takes both arms to show. Chalk it up to Bane of Bosses.","heroes":["h17"],"parties":["p4"],"loc":"thornwall","skill":"bane_of_bosses"},{"id":"e1730","day":49,"season":2,"sday":19,"kind":"road","imp":4,"text":"Mags Halloran spars with Ottoline at the roadside and ends up on her back. She laughs for the first time anyone remembers.","heroes":["h14","h10","h16","h17"],"parties":["p4"],"road":"carrbridge~thornwall","traveller":"mags","road_rec":"r343"},{"id":"e1767","day":50,"season":2,"sday":20,"kind":"ambush","imp":2,"text":"Fenwick keeps everyone up as the Tidal Almanac makes short work of 2 Swamp Trolls and a Bog Crawler on the road to Bleakmarsh. Juniper talks one swamp troll into walking away before it's over. The bog crawler had been trouble right up until Fenwick's Poisoned Blade. Ottoline never stopped moving, start to finish. Loot: 9 silver each, 3 chitin, 3 troll hide. Mags Halloran fought alongside them.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"bleakmarsh","fight":"f114","foes":["swamp_troll","bog_crawler","swamp_troll"],"where":"on the road to Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-30,"allies":"mags"},{"id":"e1782","day":50,"season":2,"sday":20,"kind":"talent","imp":1,"text":"Fenwick sharpens their weapon all evening, humming the name of the next floor's boss. Somebody asks how. 'Bane of Bosses,' says Fenwick.","heroes":["h17"],"parties":["p4"],"loc":"bleakmarsh","skill":"bane_of_bosses"},{"id":"e1794","day":51,"season":2,"sday":21,"kind":"fight","imp":2,"text":"The Tidal Almanac gets the better of 5 Risen Dead in Bleakmarsh. Ottoline's Frost Nova lit up five of them together. Juniper was everywhere at once. Loot: 11 grave dust, 9 remains.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"bleakmarsh","fight":"f117","foes":["zombie","zombie","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":1,"wx":"fog"},{"id":"e1810","day":51,"season":2,"sday":21,"kind":"talent","imp":2,"text":"Fenwick corrects Tamsin's grip while they walk. Tamsin sighs, then fixes it. The duelist's trade has a name for that: Fencing Lessons.","heroes":["h17","h16"],"parties":["p4"],"loc":"bleakmarsh","skill":"fencing_lessons","wx":"fog"},{"id":"e1833","day":52,"season":2,"sday":22,"kind":"fight","imp":3,"text":"In Bleakmarsh, 4 Giant Spiders and a Bog Crawler get in the Tidal Almanac's way, briefly. Juniper talks one bog crawler into walking away before it's over. Tamsin loosed Aimed Shot, and the giant spider dropped. Loot: 14 chitin, 8 spider legs.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"bleakmarsh","fight":"f124","foes":["giant_spider","giant_spider","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-13},{"id":"e1834","day":52,"season":2,"sday":22,"kind":"ability","imp":2,"text":"Camped alone at Bleakmarsh with an empty pot, Juniper makes soup out of a bone, some nettles and stubbornness. It's surprisingly good, and there's still a ration left in the pack for tomorrow.","heroes":["h10"],"parties":["p4"],"loc":"bleakmarsh","skill":"stretch_the_rations","sk":"Stretch the Rations","rule":true},{"id":"e1849","day":52,"season":2,"sday":22,"kind":"talent","imp":1,"text":"Tamsin takes a path nobody else can see and the party arrives a full day early.","heroes":["h16"],"parties":["p4"],"loc":"bleakmarsh","skill":"walker_of_all_roads"},{"id":"e1868","day":53,"season":2,"sday":23,"kind":"wagon","imp":3,"text":"The Tidal Almanac buys a donkey cart in Ashfen for 15 silver and hitches Juniper's pony, Muffin, to it. Muffin looks betrayed.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"ashfen"},{"id":"e1889","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Juniper talks the Ashfen cook into selling dried meat by the pound, and packs a week of it. Stretch the Rations, the guild calls it.","heroes":["h10"],"parties":["p4"],"loc":"ashfen","skill":"stretch_the_rations"},{"id":"e1896","day":53,"season":2,"sday":23,"kind":"argument","imp":3,"text":"It starts with who ate the last of the cheese. It ends with Fenwick and Tamsin sleeping on opposite sides of the fire.","heroes":["h17","h16"],"parties":["p4"]},{"id":"e1897","day":53,"season":2,"sday":23,"kind":"campfire","imp":2,"text":"Tamsin offers Fenwick a sip of milk. Fenwick declines, then accepts.","heroes":["h16","h17"],"parties":["p4"],"loc":"ashfen"},{"id":"e1912","day":54,"season":2,"sday":24,"kind":"trade","imp":2,"text":"The Tidal Almanac buys 17 moonpetal in Ashfen, betting on better prices in Hollowood.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"ashfen","wx":"storm"},{"id":"e1914","day":54,"season":2,"sday":24,"kind":"road","imp":3,"text":"A blessing from Sister Rue settles over Tamsin like a warm shawl. A curse for the road follows it, for good measure.","heroes":["h16","h10","h14","h17"],"parties":["p4"],"road":"ashfen~ashveil_crypts","traveller":"rue","road_rec":"r371"},{"id":"e1929","day":54,"season":2,"sday":24,"kind":"campfire","imp":1,"text":"Tamsin and Juniper invent a scoring system for snoring. Nobody else is consulted.","heroes":["h16","h10"],"parties":["p4"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1935","day":55,"season":2,"sday":25,"kind":"party_life","imp":1,"text":"By the third crossroads Fenwick has stopped waiting and started complaining about the wait.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e1936","day":55,"season":2,"sday":25,"kind":"road","imp":3,"text":"Twiddle presses a small bright thing into Ottoline's hand from the family stock. 'A tinker's thank-you,' says Granny Kettleby. Ottoline has been given a trinket.","heroes":["h14","h10","h16","h17"],"parties":["p4"],"road":"ashveil_crypts~hollowood","traveller":"kettleby","road_rec":"r375"},{"id":"e1955","day":55,"season":2,"sday":25,"kind":"ability","imp":2,"text":"There's a hot spring two miles off the road that isn't on any map. Tamsin knows it, of course. An hour's soak, and they walk on mended.","heroes":["h16"],"parties":["p4"],"loc":"ashveil_crypts","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true},{"id":"e1962","day":55,"season":2,"sday":25,"kind":"argument","imp":4,"text":"Juniper and Tamsin have had the same argument three times now. This time Juniper just walks away mid-sentence, which is worse. The Tidal Almanac is splitting into camps.","heroes":["h10","h16"],"parties":["p4"]},{"id":"e1981","day":56,"season":2,"sday":26,"kind":"talent","imp":1,"text":"Juniper checks the flattering mirror before bed. The face in it looks like someone who'll be fine tomorrow.","heroes":["h10"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e2047","day":58,"season":2,"sday":28,"kind":"ambush","imp":2,"text":"Two Bandit Archers and a Bandit Captain pick the wrong crew on the road to the Ashveil Crypts, and the Tidal Almanac handles them. Juniper talks one bandit captain out of the fight before it's over. The last bandit archer doesn't stay to see the end. It was even until Ottoline's Force Bolt. Then it wasn't. Ottoline landed the hit that turned it, then went straight back to guarding the packs. Tamsin kept the bleeding to a minimum. \"I'll keep this one's ear,\" says Tamsin. Loot: 2 silver each.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"kingsroad","fight":"f140","foes":["bandit_archer","bandit_archer","bandit_captain"],"where":"on the road to The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-54},{"id":"e2090","day":60,"season":2,"sday":30,"kind":"talent","imp":2,"text":"Fenwick drills Tamsin on the parry for an hour. Tamsin's parry is now a real parry.","heroes":["h17","h16"],"parties":["p4"],"loc":"ashveil_crypts","skill":"fencing_lessons"},{"id":"e2091","day":60,"season":2,"sday":30,"kind":"night","imp":2,"text":"Juniper tells a ghost story by the fire in the Ashveil Crypts. Ottoline insists on keeping the fire going until dawn. For warmth.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"ashveil_crypts"},{"id":"e2113","day":60,"season":2,"sday":30,"kind":"talent","imp":1,"text":"Juniper whittles a tiny wolf for Fenwick by the fire. Fenwick calls it silly and keeps it in a breast pocket. Somebody asks how. 'Whittling,' says Juniper.","heroes":["h10","h17"],"parties":["p4"],"loc":"ashveil_crypts","skill":"whittler"},{"id":"e2162","day":61,"season":3,"sday":1,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Mother Thornmere's Brood: Azure Edge and The Tidal Almanac. Odds are offered, mostly on whoever's buying.","heroes":["h3","h9","h1","h5","h10","h14","h16","h17"],"parties":["p3","p4"],"loc":"thornmere_ruins"},{"id":"e2166","day":61,"season":3,"sday":1,"kind":"ability","imp":2,"text":"Tamsin knows a drovers' track that skips the worst of the climb. The crew strolls in fresh, bruises healing, wondering why nobody else uses it.","heroes":["h16"],"parties":["p4"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true},{"id":"e2182","day":62,"season":3,"sday":2,"kind":"ambush","imp":2,"text":"On the road to Thornmere Ruins, 3 Giant Spiders get in the Tidal Almanac's way, briefly. Before it's over, Juniper talks one giant spider into putting the weapon down. Before Ottoline's Force Bolt it could have gone either way. Fenwick kept everyone standing (7 healed). Juniper went in first, as usual. Loot: 6 chitin, 5 spider legs.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"bleakmarsh","fight":"f143","foes":["giant_spider","giant_spider","giant_spider"],"where":"on the road to Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-25},{"id":"e2183","day":62,"season":3,"sday":2,"kind":"road","imp":3,"text":"Doctor Fabian Loom sets Juniper's sprain with a real splint and a real sermon. It is the first sound medicine he has practised in years.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"road":"bleakmarsh~thornmere_ruins","traveller":"loom","road_rec":"r436"},{"id":"e2184","day":62,"season":3,"sday":2,"kind":"night","imp":2,"text":"Ottoline tells a ghost story by the fire in Thornmere Ruins. Tamsin laughs at it, then moves their bedroll closer to the others.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins"},{"id":"e2200","day":63,"season":3,"sday":3,"kind":"delve","imp":1,"text":"The Tidal Almanac descends into Thornmere Ruins, untouched (0%).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2201","day":63,"season":3,"sday":3,"kind":"fight","imp":2,"text":"With Tamsin hitting hardest, the Tidal Almanac cuts down 3 Bog Crawlers and a Will-o'-Wisp in the gatehouse yard on floor 1 of Thornmere Ruins. Before it's over, Juniper talks one bog crawler into putting the weapon down. The last will-o'-wisp breaks and runs. Ask anyone when it turned: Tamsin's Aimed Shot. Loot: 11 chitin. Tamsin hates deep water more than anything, and fights through it anyway.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f144","foes":["wisp","bog_crawler","bog_crawler"],"where":"in the gatehouse yard on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-52,"wx":"fog"},{"id":"e2202","day":63,"season":3,"sday":3,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 1 of Thornmere Ruins at a push pace: 6 rooms (the gatehouse yard, the wayside cross, the pilgrims' hall and 3 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":6,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e2203","day":63,"season":3,"sday":3,"kind":"night","imp":1,"text":"Something small and clever gets into The Tidal Almanac's camp on floor 1 of Thornmere Ruins overnight. Tamsin wakes up 4 silver and 1 ration lighter.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2219","day":63,"season":3,"sday":3,"kind":"argument","imp":2,"text":"Fenwick and Tamsin spend supper disagreeing about the correct way to sharpen a sword, politely at first.","heroes":["h17","h16"],"parties":["p4"]},{"id":"e2225","day":64,"season":3,"sday":4,"kind":"gear","imp":3,"text":"In a sealed space off the chandlery on floor 1 of Thornmere Ruins, Juniper finds Sturdy Twin Dirks and puts them on. Sturdy: a little better protected (+1.5 armour). It is a step up from anything Juniper could buy.","heroes":["h10"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2226","day":64,"season":3,"sday":4,"kind":"skim","imp":2,"text":"Fenwick quietly pockets an extra 16 silver while The Tidal Almanac counts the rest. Nobody notices.","heroes":["h17"],"parties":["p4"],"loc":"thornmere_ruins","in_fight":"f146","wx":"fog"},{"id":"e2227","day":64,"season":3,"sday":4,"kind":"fight","imp":3,"text":"The Tidal Almanac gets the better of 2 Bog Crawlers and 2 Swamp Trolls in the bell tower's foundation stair, wet to the knee on floor 1 of Thornmere Ruins. Before it's over, Juniper talks one swamp troll into putting the weapon down. The last bog crawler turns tail. Ottoline landed Force Bolt on the swamp troll hard enough to hear from the back. Loot: 7 silver each, 2 troll hide, 5 herbs.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f146","foes":["bog_crawler","swamp_troll","bog_crawler"],"where":"in the bell tower's foundation stair, wet to the knee on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-29,"wx":"fog"},{"id":"e2229","day":64,"season":3,"sday":4,"kind":"gear","imp":1,"text":"In the bell tower's foundation stair, wet to the knee on floor 1 of Thornmere Ruins, Juniper finds a Garnet Ring of the Long Night and puts it on. Of the Long Night: much braver (+5 nerve).","heroes":["h10"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2230","day":64,"season":3,"sday":4,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 1 of Thornmere Ruins at a push pace: 5 rooms (a sealed space off the chandlery, the scriptorium, the font that still fills and 2 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":5,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great","great"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2245","day":65,"season":3,"sday":5,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 1 of Thornmere Ruins at a push pace: 1 room (the flooded side aisle).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":1,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e2246","day":65,"season":3,"sday":5,"kind":"ability","imp":2,"text":"Juniper is down to crumbs at Thornmere Ruins. She shakes out every pocket, checks the lining of her pack, and turns up a whole ration. Supper, and a quiet cheer.","heroes":["h10"],"parties":["p4"],"loc":"thornmere_ruins","skill":"stretch_the_rations","sk":"Stretch the Rations","rule":true,"wx":"fog"},{"id":"e2290","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Thornmere Ruins at a push pace: 6 rooms (the buttery, the reliquary niche, the granary and 3 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":6,"size":4,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e2291","day":66,"season":3,"sday":6,"kind":"talent","imp":2,"text":"Juniper lies back and names constellations for Ottoline. Some of them are even real. Stargazing: one of the things Juniper learned the long way round.","heroes":["h10","h14"],"parties":["p4"],"loc":"thornmere_ruins","skill":"stargazer","wx":"fog"},{"id":"e2303","day":66,"season":3,"sday":6,"kind":"meet","imp":2,"text":"A cold meeting in Thornmere Ruins: Tobias and The Tidal Almanac nod, exactly once, and go their separate ways.","heroes":["h6","h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2308","day":66,"season":3,"sday":6,"kind":"vow_progress","imp":3,"text":"The Tidal Almanac swore to die rich on day 1 of season 2. With 3,036 silver earned since, they're rich. Now they just have to stay that way until the age ends.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"cause":"e1113"},{"id":"e2322","day":67,"season":3,"sday":7,"kind":"gear","imp":4,"text":"A tall lantern with a flame that leans towards the door from the Lantern That Waits leaves the dark of Thornmere Ruins in Ottoline's pack. There isn't another. What it can do is anyone's guess until a town names it.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2323","day":67,"season":3,"sday":7,"kind":"famous_trap","imp":4,"text":"The Lantern That Waits, the trap everyone in Thornmere Ruins talks about, is disarmed at last. Ottoline did it, and kept a piece as proof.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2324","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of Thornmere Ruins at a steady pace: 3 rooms (a trapdoor in the vestry floor, black water lapping under it, The Lantern That Waits, the black pool).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":4,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["unique"],"fears":1,"wild":[]},"wx":"fog"},{"id":"e2329","day":67,"season":3,"sday":7,"kind":"meet","imp":1,"text":"Tamsin and Gorm swap stories in Thornmere Ruins while The Tidal Almanac and Azure Edge swap rumours.","heroes":["h10","h14","h16","h17","h3","h9","h1","h5"],"parties":["p4","p3"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2331","day":67,"season":3,"sday":7,"kind":"talent","imp":1,"text":"Fenwick stands at the boss's door, cracks their knuckles and knocks politely.","heroes":["h17"],"parties":["p4"],"loc":"thornmere_ruins","skill":"bane_of_bosses","wx":"fog"},{"id":"e2337","day":67,"season":3,"sday":7,"kind":"argument","imp":4,"text":"Tamsin and Ottoline have had the same argument three times now. This time Tamsin threw a boot. The Tidal Almanac is splitting into camps.","heroes":["h16","h14"],"parties":["p4"]},{"id":"e2338","day":67,"season":3,"sday":7,"kind":"talent","imp":1,"text":"Tamsin turns the crooked first nail over by the fire. It's a bad nail. It's their nail.","heroes":["h16"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2344","day":68,"season":3,"sday":8,"kind":"fight","imp":3,"text":"It's 3 Bog Crawlers and a Will-o'-Wisp against the Tidal Almanac in the tithe barn on floor 2 of Thornmere Ruins, and it isn't close. Juniper talks one bog crawler out of the fight before it's over. Fenwick called Inspire, and the line steadied. Ottoline never once gave ground. Loot: 3 bottled wisplight, 3 wisp sugar, 11 chitin.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","fight":"f161","foes":["bog_crawler","wisp","bog_crawler"],"where":"in the tithe barn on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-24,"wx":"fog"},{"id":"e2345","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 3 of Thornmere Ruins at a push pace: 5 rooms (the reed maze, the tithe barn, the granary and 2 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":5,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":3,"wild":[]},"wx":"fog"},{"id":"e2387","day":69,"season":3,"sday":9,"kind":"sniped","imp":3,"text":"Mother Thornmere's Brood was killed by Azure Edge today, and The Tidal Almanac and Tobias all hear it from the same tired messenger. Their trips are rethought on the spot.","heroes":["h1","h10","h14","h16","h17","h3","h5","h6","h9"],"parties":["p3","p4"],"loc":"thornmere_ruins","snipers":["h3","h9","h1","h5"],"where":"many","boss":"Mother Thornmere's Brood","in_fight":"f165","wx":"fog"},{"id":"e2388","day":69,"season":3,"sday":9,"kind":"rivalry","imp":3,"text":"Azure Edge again. The Tidal Almanac has lost 2 races to the same crew now. Someone at the bar starts keeping score on the wall.","heroes":["h10","h14","h16","h17","h3","h9","h1","h5"],"parties":["p4","p3"],"in_fight":"f165"},{"id":"e2393","day":69,"season":3,"sday":9,"kind":"wild_room","imp":3,"text":"Tamsin's fear of water finds a dry stair in Thornmere Ruins. Tamsin: 'I've been saying this for years.'","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","room":"wild_cowards_stair","wx":"fog"},{"id":"e2394","day":69,"season":3,"sday":9,"kind":"gear","imp":1,"text":"In a walled-up room beside the smugglers' dry stair on floor 3 of Thornmere Ruins, Tamsin finds a Quick Delver's Strap and puts it on. Quicker (+0.8 speed).","heroes":["h16"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2395","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 3 of Thornmere Ruins at a steady pace: 4 rooms (the smugglers' dry stair, a walled-up room beside the smugglers' dry stair, the priests' cells and 1 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"size":4,"floor":3,"traps":0,"sprung":1,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":2,"wild":["wild_cowards_stair"]},"wx":"fog"},{"id":"e2407","day":69,"season":3,"sday":9,"kind":"meet","imp":1,"text":"Tobias spots The Tidal Almanac in Thornmere Ruins and takes the long way round. Half a day lost. Worth it.","heroes":["h6","h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2414","day":69,"season":3,"sday":9,"kind":"argument","imp":2,"text":"Juniper and Fenwick are not speaking. It's about whether ghosts can be bribed. It's never really about whether ghosts can be bribed.","heroes":["h10","h17"],"parties":["p4"]},{"id":"e2422","day":70,"season":3,"sday":10,"kind":"delve_done","imp":3,"text":"The Tidal Almanac climbs out at last, 8 days older and a good deal dirtier. They found the wayside cross, a sealed space off the chandlery, the bell tower's foundation stair, wet to the knee and 8 more good rooms, went as deep as the place goes, cleared 29 rooms, disarmed 2 traps, mapped 64% of it, split 381 silver on the way up and turned back because their nerves were fraying. Not the trip they set out on, but a trip. All the crews' maps laid side by side say Thornmere Ruins is mostly explored (68%).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","days":8,"bottom":true,"rooms":["the wayside cross","a sealed space off the chandlery"],"gold":381,"turn":"nerve","wx":"fog"},{"id":"e2456","day":71,"season":3,"sday":11,"kind":"party_life","imp":1,"text":"Tamsin arrives at camp an hour behind Fenwick and finds the good spot by the fire taken.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2472","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"A cold night on the road, but nobody near Ottoline notices. (Kindled Soul, if anyone's asking.)","heroes":["h14"],"parties":["p4"],"loc":"bleakmarsh","skill":"kindled_soul","wx":"fog"},{"id":"e2473","day":71,"season":3,"sday":11,"kind":"ability","imp":2,"text":"Tamsin walks an old king's road that has been grass for a century, its stones still flat under the turf. They arrive with their cuts healed and their head clear.","heroes":["h16"],"parties":["p4"],"loc":"bleakmarsh","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"fog"},{"id":"e2484","day":71,"season":3,"sday":11,"kind":"goal","imp":1,"text":"After a long night's talk, The Tidal Almanac settles on a goal: to earn 500 silver between them before the season ends.","heroes":["h10","h14","h16"],"parties":["p4"]},{"id":"e2524","day":72,"season":3,"sday":12,"kind":"goal_progress","imp":2,"text":"The Tidal Almanac is getting close: earn 500 silver between them before the season ends (341 of 500 silver).","heroes":["h10","h14","h16","h17"],"parties":["p4"]},{"id":"e2534","day":73,"season":3,"sday":13,"kind":"party_life","imp":1,"text":"Tamsin spends the whole road in the dust Fenwick kicks up, and says so.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"carrbridge"},{"id":"e2551","day":73,"season":3,"sday":13,"kind":"campfire","imp":3,"text":"Ottoline and Tamsin both reach for the same stool at The Honest Toll. Ottoline lets Tamsin have it, this once.","heroes":["h14","h16"],"parties":["p4"],"loc":"carrbridge"},{"id":"e2609","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Fenwick keeps a list of bosses on a Saltmarrow tavern wall. The landlord adds a second wall.","heroes":["h17"],"parties":["p4"],"loc":"saltmarrow","skill":"bane_of_bosses","wx":"storm"},{"id":"e2611","day":75,"season":3,"sday":15,"kind":"talent","imp":1,"text":"Juniper gets a Saltmarrow merchant down from twelve silver to nine by sighing at exactly the right moments.","heroes":["h10"],"parties":["p4"],"loc":"saltmarrow","skill":"haggler","wx":"storm"},{"id":"e2622","day":75,"season":3,"sday":15,"kind":"goal_done","imp":4,"text":"The Tidal Almanac can cross it off: earn 500 silver between them before the season ends. Drinks are on them. XP: Juniper +960 (level 16!), Ottoline +960 (level 16!), Tamsin +960 (level 17!), Fenwick +960 (level 16!).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"xp":{"h10":960,"h14":960,"h16":960,"h17":960}},{"id":"e2642","day":76,"season":3,"sday":16,"kind":"trade","imp":2,"text":"The Tidal Almanac buys 11 gems in Saltmarrow, betting on better prices in Carrbridge.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"saltmarrow","wx":"storm"},{"id":"e2643","day":76,"season":3,"sday":16,"kind":"road","imp":3,"text":"Granfer Oake shows Fenwick how birds act before the rain. Fenwick will now never be unready for it again.","heroes":["h17","h10","h14","h16"],"parties":["p4"],"road":"carrbridge~saltmarrow","traveller":"oake","road_rec":"r510"},{"id":"e2656","day":76,"season":3,"sday":16,"kind":"talent","imp":1,"text":"Tamsin rebuilds a stile that's been broken for years. A farmer watches, nods, and drops off a ham. Tamsin puts it down to Carpentry.","heroes":["h16"],"parties":["p4"],"loc":"saltmarrow","skill":"carpenter","wx":"storm"},{"id":"e2689","day":77,"season":3,"sday":17,"kind":"ability","imp":2,"text":"Tamsin takes Fenwick and the rest along an old smugglers' path: flat, shady, with a spring halfway. They arrive in better shape than they set out.","heroes":["h16","h17"],"parties":["p4"],"loc":"saltmarrow","skill":"walker_of_all_roads","sk":"Walker of All Roads","rule":true,"wx":"storm"},{"id":"e2739","day":79,"season":3,"sday":19,"kind":"road","imp":2,"text":"Pim offers Juniper a heel of bread for the first time and glances over their shoulder to see who is following.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"road":"carrbridge~saltmarrow","traveller":"pim","road_rec":"r535"},{"id":"e2757","day":79,"season":3,"sday":19,"kind":"campfire","imp":1,"text":"Juniper orders Tamsin a milk before Tamsin even sits down. Remembering an order is how it starts.","heroes":["h16","h10"],"parties":["p4"],"loc":"carrbridge","wx":"heat"},{"id":"e2790","day":80,"season":3,"sday":20,"kind":"party_strain","imp":3,"text":"Fenwick is restless. The Tidal Almanac is too careful for Fenwick's liking, and Fenwick has started saying so.","heroes":["h17"],"parties":["p4"],"loc":"carrbridge","wx":"heat"},{"id":"e2819","day":81,"season":3,"sday":21,"kind":"talent","imp":2,"text":"Tamsin signs a joke across the noisy Saltmarrow tavern to Ottoline. Ottoline snorts ale. Hand Signs, the way the drill-yards teach it.","heroes":["h16","h14"],"parties":["p4"],"loc":"saltmarrow","skill":"hand_signs"},{"id":"e2842","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Juniper lays out their pilgrim tokens by the fire and tells Tamsin where each one came from. Pilgrim all the way, Juniper insists.","heroes":["h10","h16"],"parties":["p4"],"loc":"saltcliffs","skill":"pilgrim"},{"id":"e2857","day":82,"season":3,"sday":22,"kind":"party_leave","imp":3,"text":"Fenwick leaves The Tidal Almanac: wants real fights, not this.","heroes":["h17","h10","h14","h16"],"parties":["p4"],"loc":"saltcliffs"},{"id":"e2912","day":84,"season":3,"sday":24,"kind":"delve","imp":1,"text":"The Tidal Almanac descends into the Sunken Vault, partly explored (49%).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e2914","day":84,"season":3,"sday":24,"kind":"fight","imp":1,"text":"The Tidal Almanac runs into 2 Cliff Crabs and the Drowned in the swallowed ship on floor 1 of the Sunken Vault and comes out on top. Juniper talks one cliff crab into walking away before it's over. The last cliff crab turns tail. Tamsin's Aimed Shot was where the fight changed hands. Loot: 4 trinkets, 5 barnacle oysters. Tamsin, who has been afraid of deep water since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"sunken_vault","fight":"f200","foes":["crab","drowned","crab"],"where":"in the swallowed ship on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-26},{"id":"e2915","day":84,"season":3,"sday":24,"kind":"fight","imp":2,"text":"With Juniper taking the worst of it, the Tidal Almanac beats 2 Drowned and a Siren in the undertow passage on floor 1 of the Sunken Vault. Before it's over, Juniper talks one siren into putting the weapon down. Ottoline's Cold Snap slowed the Drowned to a crawl. Ask the others what won it: Tamsin's Bramble Snare. Loot: 4 remains, 11 trinkets, 10 barnacle oysters.","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"sunken_vault","fight":"f201","foes":["drowned","siren","drowned"],"where":"in the undertow passage on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-50},{"id":"e2916","day":84,"season":3,"sday":24,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 1 of the Sunken Vault at a steady pace: 3 rooms (the swallowed ship, the undertow passage, the tellers' cages).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2921","day":84,"season":3,"sday":24,"kind":"boss_race","imp":3,"text":"The Tidal Almanac and Fenwick are headed for the same hole in the ground: The Sunken Vault, where The Kraken of the Vault waits. Somebody is going to be disappointed.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e2949","day":85,"season":3,"sday":25,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of the Sunken Vault at a steady pace: 2 rooms (the old strongroom, the bonded warehouse).","heroes":["h10","h14","h16"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2950","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Juniper reconstructs the week's spending to the copper, from memory. The crew is alarmed and grateful.","heroes":["h10"],"parties":["p4"],"loc":"sunken_vault","skill":"price_memory","wx":"fog"},{"id":"e2962","day":85,"season":3,"sday":25,"kind":"party_join","imp":3,"text":"Fenwick walks back into The Tidal Almanac after 3 days on their own. The real fights, it turns out, are better with friends. Nobody says 'told you so' out loud.","heroes":["h17","h10","h14","h16"],"parties":["p4"],"loc":"sunken_vault","wx":"fog"},{"id":"e2969","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Fenwick walks the camp edge at dusk, hanging little bells on strings. Nothing gets in unheard. Chalk it up to Trapfinder.","heroes":["h17"],"parties":["p4"],"loc":"sunken_vault","skill":"trapfinder","wx":"fog"},{"id":"e2970","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Tamsin replays the last fight for Juniper blow by blow. In this version, both are heroes. Both were.","heroes":["h10","h16"],"parties":["p4"],"loc":"sunken_vault","wx":"fog"},{"id":"e2985","day":86,"season":3,"sday":26,"kind":"fight","imp":1,"text":"In the serpent's coil on floor 2 of the Sunken Vault, the Tidal Almanac handles a Sea Serpent. Ask anyone when it turned: Ottoline's Firebolt. Ottoline did the unglamorous work that kept the line from breaking. Loot: 12 fangs & claws, 6 serpent fillets.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","fight":"f205","foes":["sea_serpent"],"where":"in the serpent's coil on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-1,"wx":"fog"},{"id":"e2986","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 2 of the Sunken Vault at a steady pace: 4 rooms (the coin vaults, the serpent's coil, the guards' mess and 1 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e2987","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Tamsin uses the first nail to fix a tent peg, then takes it back out.","heroes":["h16"],"parties":["p4"],"loc":"sunken_vault","wx":"fog"},{"id":"e3026","day":87,"season":3,"sday":27,"kind":"fight","imp":2,"text":"It's 4 Cliff Crabs against the Tidal Almanac in the bullion cellar on floor 2 of the Sunken Vault, and it isn't close. Before it's over, Juniper talks one cliff crab into putting the weapon down. The last cliff crab breaks and runs. That Frost Nova from Ottoline was the moment it tipped. Loot: 8 chitin, 6 fish, 9 cliff crab claws.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","fight":"f208","foes":["crab","crab","crab"],"where":"in the bullion cellar on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-46,"wx":"fog"},{"id":"e3027","day":87,"season":3,"sday":27,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 3 of the Sunken Vault at a steady pace: 2 rooms (the bullion cellar, the glowing reef).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":2,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e3043","day":87,"season":3,"sday":27,"kind":"curio","imp":1,"text":"Ottoline trades a Bell off a Cat's Collar to Juniper for a Hollowood Knot-Charm. Both think they won.","heroes":["h14","h10"],"parties":["p4"],"loc":"sunken_vault","wx":"fog"},{"id":"e3060","day":88,"season":3,"sday":28,"kind":"gear","imp":3,"text":"In a hidden room behind the captain's cabin on floor 3 of the Sunken Vault, Juniper finds Tidebound Fine Stilettos and puts them on. Salt-Hardened: tougher (+4% health). It is a step up from anything Juniper could buy.","heroes":["h10"],"parties":["p4"],"loc":"sunken_vault","wx":"fog"},{"id":"e3061","day":88,"season":3,"sday":28,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 3 of the Sunken Vault at a cautious pace: 3 rooms (the captain's cabin, a hidden room behind the captain's cabin, the glowing reef).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":3,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common","great"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e3098","day":89,"season":3,"sday":29,"kind":"fight","imp":2,"text":"The Tidal Almanac, in fine spirits lately, defeats 3 Drowned in the lower guard-post on floor 3 of the Sunken Vault. Frost from Tamsin's Bramble Snare had the Drowned stumbling. Without Fenwick's Hold the Line, this goes differently. Loot: 36 trinkets, 16 remains, 18 barnacle oysters.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","fight":"f214","foes":["drowned","drowned","drowned"],"where":"in the lower guard-post on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e3099","day":89,"season":3,"sday":29,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 3 of the Sunken Vault at a cautious pace: 3 rooms (the lower guard-post, the kelp-choked stair, the sea-cave breach).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":3,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":3,"wild":[]}},{"id":"e3100","day":89,"season":3,"sday":29,"kind":"ability","imp":2,"text":"Fenwick is sure the last of the food went yesterday. Juniper produces a ration from a boot. Nobody asks which boot. The crew eats in cheerful silence.","heroes":["h10","h17"],"parties":["p4"],"loc":"sunken_vault","skill":"stretch_the_rations","sk":"Stretch the Rations","rule":true},{"id":"e3122","day":89,"season":3,"sday":29,"kind":"campfire","imp":1,"text":"Ottoline and Juniper share a crab caught in the stairwell. It is small and hard work, and it is the best meal of the trip.","heroes":["h14","h10"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e3138","day":90,"season":3,"sday":30,"kind":"gear","imp":1,"text":"In the pearl bed on floor 3 of the Sunken Vault, Tamsin finds a pair of Salt-Hardened Pathfinder's Boots and puts them on. Salt-Hardened: tougher (+4% health).","heroes":["h16"],"parties":["p4"],"loc":"sunken_vault"},{"id":"e3139","day":90,"season":3,"sday":30,"kind":"fight","imp":1,"text":"The Tidal Almanac cuts down a Sea Serpent in the serpent's coil on floor 3 of the Sunken Vault without much fuss. The sea serpent spent the rest of the fight on fire, courtesy of Ottoline's Firebolt. Loot: 18 fangs & claws.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","fight":"f217","foes":["sea_serpent"],"where":"in the serpent's coil on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e3140","day":90,"season":3,"sday":30,"kind":"delve_day","imp":1,"text":"The Tidal Almanac works floor 3 of the Sunken Vault at a steady pace: 5 rooms (the deposit boxes, the wall of the unclaimed, the pearl bed and 2 more).","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":5,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":3,"wild":[]}},{"id":"e3141","day":90,"season":3,"sday":30,"kind":"talent","imp":2,"text":"Ottoline makes a tiny storm over Tamsin's tea: lightning, hail, a small rainbow. Tamsin drinks it anyway.","heroes":["h14","h16"],"parties":["p4"],"loc":"sunken_vault","skill":"elemental_tricks"},{"id":"e3148","day":90,"season":3,"sday":30,"kind":"talent","imp":1,"text":"Juniper stops, sniffs, and puts a hand on a wall at the Sunken Vault. Behind it, a pouch of very old coins.","heroes":["h10"],"parties":["p4"],"loc":"sunken_vault","skill":"treasure_sense"},{"id":"e3157","day":90,"season":3,"sday":30,"kind":"delve_done","imp":3,"text":"The Tidal Almanac comes up for air after 7 days, pockets heavier and boots wetter. They turned up the tellers' cages, the old strongroom, the coin vaults and 7 more good rooms, got down to floor 3, inked 28% of the map, cleared 22 rooms and came away with 513 silver between them. The Sunken Vault is mostly explored (74%), going by everyone's notes.","heroes":["h10","h14","h16","h17"],"parties":["p4"],"loc":"sunken_vault","days":7,"bottom":false,"rooms":["the tellers' cages","the old strongroom"],"gold":513},{"id":"e3168","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Lantern of Carrbridge, to die rich (sworn in season 2); Azure Edge, never to pay a toll (sworn in season 1); The Tidal Almanac, never to retreat (sworn in season 2); The Tidal Almanac, to die rich (sworn in season 2); The White Quills, to keep the peace: never draw first on another hero (sworn in season 1); Cobalt Mercy, to die rich (sworn in season 2); Tobias, never to pay a toll (sworn in season 2); Juniper, never to retreat (sworn in season 1). Every one of them held.","heroes":["h10","h6"],"parties":["p1","p3","p4","p5","p6"]}],"roles":{"h10":"Leader · Scout","h16":"Blade","h17":"Face","h14":"Spellcaster"},"quest":{"what":"Delve","where":"The Sunken Vault","why":"chasing a rumour: about 45 silver a day each, risk slight; the vow: to die rich; Juniper's last chance at the dream before the age ends","floor":2,"floors":4},"tactics":{"front":["h10","h17"],"back":["h14","h16"],"plan":"Juniper and Fenwick hold the front; Ottoline casts from behind; Tamsin picks off whatever gets close.","traits":{"boldness":0.36,"risk":0.32,"greed":0.15,"sociability":-0.11,"honor":0.05,"curiosity":0.23,"temper":0.24,"loyalty":0.08},"mix":"2 bows, 1 talker, 1 caster","notes":["No healer: every wound comes home with them."],"style":["bold","reckless","balanced"],"skills":[{"label":"Damage","skills":[{"hero":"h16","id":"aimed_shot","name":"Aimed Shot","desc":"Breathes out. Lets go.","tags":["crit"],"rank":3,"uses":22},{"hero":"h14","id":"force_bolt","name":"Force Bolt","desc":"An invisible fist, thrown from across the room.","tags":["arcane"],"rank":1,"uses":17},{"hero":"h14","id":"firebolt","name":"Firebolt","desc":"The classic.","tags":["fire"],"rank":2,"uses":9},{"hero":"h17","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":1,"uses":7},{"hero":"h14","id":"steam_burst","name":"Steam Burst","desc":"Fire meets ice. Everyone gets a facial.","tags":["fire","ice"],"rank":1,"uses":6},{"hero":"h14","id":"dirty_fighting","name":"Dirty Fighting","desc":"Sand in the eyes. Classic.","tags":["rage"],"rank":1,"uses":5},{"hero":"h14","id":"frost_nova","name":"Frost Nova","desc":"The air cracks white.","tags":["ice"],"rank":1,"uses":5},{"hero":"h17","id":"feint","name":"Feint","desc":"Look over there.","tags":["stealth","crit"],"rank":1,"uses":4},{"hero":"h17","id":"poisoned_blade","name":"Poisoned Blade","desc":"A smear of something green along the edge.","tags":["stealth"],"rank":2,"uses":2},{"hero":"h17","id":"lunge","name":"Lunge","desc":"Long step, longer reach.","tags":["crit"],"rank":3,"uses":2},{"hero":"h14","id":"flame_jet","name":"Flame Jet","desc":"Two quick gouts from the fingertips.","tags":["fire"],"rank":1,"uses":1},{"hero":"h14","id":"meteor","name":"Meteor","desc":"Calls down the sky.","tags":["fire"],"rank":1,"uses":0}]},{"label":"Defence","skills":[{"hero":"h17","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":1,"uses":23},{"hero":"h17","id":"hold_the_line","name":"Hold the Line","desc":"Nobody steps back. Nobody.","tags":["guard","command"],"rank":2,"uses":22},{"hero":"h17","id":"intercept","name":"Intercept","desc":"Steps in front of the blow meant for a friend.","tags":["guard"],"rank":1,"uses":0}]},{"label":"Tricks","skills":[{"hero":"h10","id":"pay_them_off","name":"Pay Them Off","desc":"Throws a purse. One of them picks it up and goes home.","tags":["trade"],"rank":2,"uses":13},{"hero":"h16","id":"bramble_snare","name":"Bramble Snare","desc":"Brambles, plaited into something that holds.","tags":["nature","craft"],"rank":1,"uses":13},{"hero":"h14","id":"cold_snap","name":"Cold Snap","desc":"The temperature drops ten degrees, on purpose.","tags":["ice"],"rank":1,"uses":4},{"hero":"h14","id":"kindled_soul","name":"Kindled Soul","desc":"Runs warm. Dangerously warm.","tags":[],"rank":1,"uses":3},{"hero":"h16","id":"snare_field","name":"Snare Field","desc":"Half the enemy finds the snares. The other half finds out.","tags":["nature","craft"],"rank":1,"uses":3},{"hero":"h14","id":"mirror_image","name":"Mirror Image","desc":"There are three of them. The monster picks wrong.","tags":["stealth"],"rank":1,"uses":1},{"hero":"h17","id":"bane_of_bosses","name":"Bane of Bosses","desc":"The bigger the crown, the louder it falls.","tags":[],"rank":1,"uses":1}]},{"label":"Always on","skills":[{"hero":"h10","id":"aura_of_courage","name":"Aura of Courage","desc":"Nobody runs while they stand.","tags":["holy","command"],"rank":3,"uses":0},{"hero":"h10","id":"coin_shield","name":"Coin Shield","desc":"Buys the best armor. Obviously.","tags":["trade","guard"],"rank":1,"uses":0},{"hero":"h16","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":2,"uses":0},{"hero":"h16","id":"quick_feet","name":"Quick Feet","desc":"First in, first out.","tags":["travel","stealth"],"rank":2,"uses":0}]},{"label":"On the road","skills":[{"hero":"h10","id":"haggler","name":"Haggler","desc":"Squeezes every merchant for an extra silver.","tags":["trade"],"rank":2,"uses":0},{"hero":"h10","id":"price_memory","name":"Price Memory","desc":"Never forgets what a candle cost three winters ago.","tags":["trade"],"rank":2,"uses":0},{"hero":"h10","id":"bulk_trader","name":"Bulk Trader","desc":"Buys a mule. Then another.","tags":["trade","travel"],"rank":2,"uses":0},{"hero":"h10","id":"pilgrim","name":"Pilgrim","desc":"Every road leads to a shrine, if you walk it right.","tags":["holy","travel"],"rank":1,"uses":0},{"hero":"h10","id":"supply_master","name":"Supply Master","desc":"Gets supplies at cost.","tags":["trade"],"rank":1,"uses":0},{"hero":"h10","id":"whittler","name":"Whittling","desc":"Turns every stick into a small duck.","tags":[],"rank":1,"uses":0},{"hero":"h10","id":"stargazer","name":"Stargazing","desc":"Can find north, the Swan, and the Little Ladle.","tags":["travel","lore"],"rank":1,"uses":0},{"hero":"h10","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h10","id":"treasure_sense","name":"Treasure Sense","desc":"Can smell gold through a wall.","tags":["trade"],"rank":1,"uses":0},{"hero":"h14","id":"charcoal_burner","name":"Charcoal Burner","desc":"Burns charcoal on rest days. The blacksmith buys every sack.","tags":["fire"],"rank":1,"uses":0},{"hero":"h14","id":"fire_eater","name":"Fire Eater","desc":"Eats fire. Never orders hot soup.","tags":[],"rank":1,"uses":0},{"hero":"h14","id":"elemental_tricks","name":"Elemental Tricks","desc":"Fire in one hand, ice in the other. Children scream; parents tip.","tags":["fire","ice"],"rank":2,"uses":0},{"hero":"h14","id":"fire_watch","name":"Fire Watch","desc":"Sleeps beside the fire. Wakes before the wolves do.","tags":["fire"],"rank":2,"uses":0},{"hero":"h14","id":"smelters_touch","name":"Smelter's Touch","desc":"Heats metal by hand. Smiths pay for it.","tags":["fire"],"rank":1,"uses":0},{"hero":"h14","id":"hearthfire","name":"Hearthfire","desc":"Lights any fire, in any weather.","tags":["fire"],"rank":1,"uses":0},{"hero":"h16","id":"whetstone","name":"Whetstone","desc":"Sharpens everything. Has been asked to stop.","tags":["craft"],"rank":1,"uses":0},{"hero":"h16","id":"hand_signs","name":"Hand Signs","desc":"Can say 'goblins, three, left' without a sound.","tags":["stealth"],"rank":2,"uses":0},{"hero":"h16","id":"wanderlust","name":"Wanderlust","desc":"Every road teaches something.","tags":["travel"],"rank":1,"uses":0},{"hero":"h16","id":"knot_tying","name":"Knotwork","desc":"Knows forty knots and when to use thirty-nine of them.","tags":["travel","craft"],"rank":2,"uses":0},{"hero":"h16","id":"rumourmonger","name":"Rumourmonger","desc":"Hears everything first. Repeats most of it.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h16","id":"carpenter","name":"Carpentry","desc":"Measures twice, cuts once, builds a bench.","tags":["craft"],"rank":1,"uses":0},{"hero":"h16","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h17","id":"spelunker","name":"Spelunker","desc":"Happiest in a crack the width of a loaf.","tags":["travel","stealth"],"rank":1,"uses":0},{"hero":"h17","id":"trapfinder","name":"Trapfinder","desc":"Steps around the flagstone everyone else steps on.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h17","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h17","id":"fencing_lessons","name":"Fencing Lessons","desc":"Teaches the basics. Charges for the advanced.","tags":["crit"],"rank":2,"uses":0},{"hero":"h17","id":"scavenger","name":"Scavenger","desc":"Checks every pocket, every boot, every crevice.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h10","dmg":800,"healed":0,"taken":422,"kills":8,"row":"front"},{"hero":"h14","dmg":1895,"healed":0,"taken":0,"kills":4,"row":"back"},{"hero":"h16","dmg":1304,"healed":0,"taken":0,"kills":6,"row":"back"},{"hero":"h17","dmg":150,"healed":94,"taken":180,"kills":2,"row":"front"}],"ground":{"name":"The Sunken Vault","fights":6}},"trophies":[]};